"""Degree-versus-depth demo: on interval graphs a vertex degree is bounded by endpoint depth.

For each variable we compare its interference degree with the depths at its two endpoints. This
illustrates why degree-based spilling tracks geometric congestion: the maximum-degree vertex
always sits near a deepest point.
"""
from __future__ import annotations
from itertools import combinations
from typing import List, Tuple

Interval = Tuple[int, int]


def interfere(a: Interval, b: Interval) -> bool:
    return a[0] <= b[1] and b[0] <= a[1]


def depth_at(ranges: List[Interval], t: int) -> int:
    return sum(1 for (lo, hi) in ranges if lo <= t <= hi)


def degree(ranges: List[Interval], i: int) -> int:
    return sum(1 for j in range(len(ranges)) if j != i and interfere(ranges[i], ranges[j]))


if __name__ == "__main__":
    program = [(0, 3), (1, 5), (2, 6), (4, 8), (7, 10)]
    print("var | degree | depth(lo) | depth(hi) | max(depths)-1")
    for i, (lo, hi) in enumerate(program):
        dlo, dhi = depth_at(program, lo), depth_at(program, hi)
        print(f"  {i} |   {degree(program, i)}    |     {dlo}     |     {dhi}     |      {max(dlo, dhi) - 1}")
    print("\nObserve: degree(i) <= depth(lo_i) + depth(hi_i) - 2 on interval graphs.")

