from typing import Dict, List, Tuple

Interval = Tuple[int, int]


def interfere(a: Interval, b: Interval) -> bool:
    return a[0] <= b[1] and b[0] <= a[1]


def optimal_coloring(ranges: List[Interval]) -> Dict[int, int]:
    """Optimal register assignment via earliest-start-first greedy coloring.

    Coloring in order of increasing start point is the reverse of the latest-start-first
    perfect elimination ordering. When a vertex is colored, its already-colored interfering
    neighbors all have smaller start points and are hence live at its own start point, so fewer
    than D colors are forbidden and a register among D is always free. Uses exactly D colors.
    """
    order = sorted(range(len(ranges)), key=lambda i: ranges[i][0])
    color: Dict[int, int] = {}
    for v in order:
        forbidden = {color[u] for u in color if interfere(ranges[v], ranges[u])}
        c = 0
        while c in forbidden:
            c += 1
        color[v] = c
    return color
